package main

import (
	"os"
	"strings"
	"unicode/utf8"

	"github.com/dnf/hecatron/internal/generate"
)

// banner is `hecatron banner --generator PATH [--source PATH] [--regenerate
// CMD] [--prefix P] [--suffix S]`, manage.py's cmd_banner: the DO NOT EDIT
// banner for a project's own code generator. Argument forms argparse reads
// otherwise (a missing --generator, an abbreviated option, a value starting
// with "-") are left to it, as are arguments that aren't UTF-8 and an
// environment where Python's stdout may not be UTF-8: the banner's frame
// isn't ASCII.
func (c *cli) banner() (int, bool) {
	args, ok := parseManageArgs(c.args, nil, []string{"--generator", "--source", "--regenerate", "--prefix", "--suffix"}, 0)
	if !ok || !pythonWritesUTF8() {
		return 0, false
	}
	generator, ok := args.values["--generator"]
	if !ok {
		return 0, false
	}
	for _, arg := range c.args {
		if !utf8.ValidString(arg) {
			return 0, false
		}
	}
	prefix, ok := args.values["--prefix"]
	if !ok {
		prefix = "# "
	}
	rows := []string{"This file is auto-generated by:", "  " + generator, ""}
	if source := args.values["--source"]; source != "" {
		rows = append(rows, "Source: "+source)
	} else {
		rows = append(rows, "Changes will be overwritten when it regenerates.")
	}
	if regenerate := args.values["--regenerate"]; regenerate != "" {
		rows = append(rows, "To regenerate: "+regenerate)
	} else {
		rows = append(rows, "Edit the generator or its input instead.")
	}
	_, _ = os.Stdout.WriteString(generate.Banner(rows, prefix, args.values["--suffix"]))
	return 0, true
}

// pythonWritesUTF8 is whether Python's stdout is surely UTF-8 here: no
// PYTHONIOENCODING, UTF-8 mode not turned off, and a locale that is C or
// POSIX (which Python coerces to UTF-8) or names UTF-8.
func pythonWritesUTF8() bool {
	if os.Getenv("PYTHONIOENCODING") != "" {
		return false
	}
	if mode := os.Getenv("PYTHONUTF8"); mode != "" && mode != "1" {
		return false
	}
	locale := ""
	for _, name := range []string{"LC_ALL", "LC_CTYPE", "LANG"} {
		if locale = os.Getenv(name); locale != "" {
			break
		}
	}
	lower := strings.ToLower(locale)
	return locale == "" || locale == "C" || locale == "POSIX" ||
		strings.Contains(lower, "utf-8") || strings.Contains(lower, "utf8")
}
